-- =====================================================================
-- Datos iniciales de demostración
-- =====================================================================
-- Escenario: 10 distribuidoras del departamento de Maldonado, con
-- catálogo de marcas uruguayas y precios mayoristas en pesos uruguayos
-- (referencia: Tienda Inglesa, relevado el 2026-10-20), 8 comercios
-- compradores, pedidos en todos los estados, planes de reparto y notificaciones.
--
-- Cómo cargarlo (sobre una base vacía):
--   psql -d <base> -f BaseDeDatos/DB_Tesis.sql
--   psql -d <base> -f BaseDeDatos/seed_demo.sql
--
-- Cuentas de demostración (todas con la misma contraseña: 12345678):
--   Distribuidoras: +59899100001 a +59899100010
--   Compradores:    +59899200001 a +59899200008
--
-- Las fechas son relativas al momento de la carga, así que la demo siempre
-- se ve actual. Imágenes en backend/public/uploads/demo/ (créditos en
-- backend/public/uploads/demo/CREDITOS.md).
-- =====================================================================

SET client_encoding = 'UTF8';

